function_name: distributeRewards
code: function distributeRewards() external override {
        uint8 poolId = VaultProxy(payable(address(this))).poolId();
        uint256 validatorId = VaultProxy(payable(address(this))).id();
        IStaderConfig staderConfig = VaultProxy(payable(address(this))).staderConfig();
        uint256 totalRewards = address(this).balance;
        if (!staderConfig.onlyOperatorRole(msg.sender) && totalRewards > staderConfig.getRewardsThreshold()) {
            emit DistributeRewardFailed(totalRewards, staderConfig.getRewardsThreshold());
            revert InvalidRewardAmount();
        }
        if (totalRewards == 0) {
            revert NotEnoughRewardToDistribute();
        }
        (uint256 userShare, uint256 operatorShare, uint256 protocolShare) = IPoolUtils(staderConfig.getPoolUtils())
            .calculateRewardShare(poolId, totalRewards);
        IStaderStakePoolManager(staderConfig.getStakePoolManager()).receiveWithdrawVaultUserShare{value: userShare}();
        UtilLib.sendValue(payable(staderConfig.getStaderTreasury()), protocolShare);
        IOperatorRewardsCollector(staderConfig.getOperatorRewardsCollector()).depositFor{value: operatorShare}(
            getOperatorAddress(poolId, validatorId, staderConfig)
        );
        emit DistributedRewards(userShare, operatorShare, protocolShare);
    }
vulnerability: Theft of validator principal via reward distribution
reason: The function uses address(this).balance as totalRewards and distributes it according to reward shares without verifying whether the validator has already withdrawn. After a validator exits, the withdrawal vault receives the 32 ETH principal before settleFunds is called. Any address with the operator role can call distributeRewards during this window if the balance exceeds the rewards threshold, causing the entire principal to be treated as rewards. The operator of the validator receives a large operatorShare, the protocol receives a protocolShare, and the users receive only a fractional userShare of their principal. An attacker can become an operator (e.g., via the permissionless pool), monitor for withdrawn validators, and front-run settleFunds to steal user funds. Even an unrelated operator can profit indirectly if they hold ETHx, because the increased userShare sent to the stake pool manager raises the exchange rate, while the victim operator bears the loss.
